const formatter = new Intl.RelativeTimeFormat("en", { numeric: "auto" });

const SECOND = 1000;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;
const WEEK = 7 * DAY;
const MONTH = 30.436875 * DAY; // average Gregorian month
const YEAR = 365.2425 * DAY; // average Gregorian year

/**
 * Describes how far `date` is from `now` (default: the current time) in English,
 * e.g. "just now", "5 minutes ago", "yesterday", "last week", "in 3 hours".
 *
 * Differences under 45 seconds yield "just now". Otherwise the largest fitting unit
 * among minutes, hours, days, weeks, months and years is used.
 * Throws a RangeError if either date is invalid.
 */
export function formatRelativeTime(date: Date, now: Date = new Date()): string {
  const diff = date.getTime() - now.getTime();
  if (Number.isNaN(diff)) {
    throw new RangeError("Invalid date");
  }

  const abs = Math.abs(diff);
  const sign = diff < 0 ? -1 : 1;

  if (abs < 45 * SECOND) {
    return "just now";
  }

  const minutes = Math.max(1, Math.round(abs / MINUTE));
  if (minutes < 60) {
    return formatter.format(sign * minutes, "minute");
  }

  const hours = Math.round(abs / HOUR);
  if (hours < 24) {
    return formatter.format(sign * hours, "hour");
  }

  const days = Math.round(abs / DAY);
  if (days < 7) {
    return formatter.format(sign * days, "day");
  }

  const months = Math.round(abs / MONTH);
  if (months < 1) {
    const weeks = Math.max(1, Math.round(abs / WEEK));
    return formatter.format(sign * weeks, "week");
  }
  if (months < 12) {
    return formatter.format(sign * months, "month");
  }

  const years = Math.max(1, Math.round(abs / YEAR));
  return formatter.format(sign * years, "year");
}
